mapper.select:
SELECT A.SEQ_NO seqNo, A.GENERATE_TIME generateTime, A.FIN_PRODUCT_CODE finProductCode, A.BRANCH, A.RISK_LEVEL riskLevel, A.AJUST_RISK_LEVEL ajustRiskLevel, A.IS_LAST, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME, B.FINPROD_ABBR finprodAbbr FROM PRD_RISK_LEVEL A LEFT JOIN FIN_PRODUCT B ON A.FIN_PRODUCT_CODE=B.FINPROD_MARKET_ID WHERE 1=1
AND A.FIN_PRODUCT_CODE=#{finProductCode}
AND DATE_FORMAT(A.GENERATE_TIME,'%Y-%m-%d')>=#{startDate} AND DATE_FORMAT(A.GENERATE_TIME,'%Y-%m-%d')<=#{endDate}
AND A.BRANCH=0 AND A.IS_LAST=#{isLast}

select  SEQ_NO seqNo
from PRD_RISK_LEVEL
where FIN_PRODUCT_CODE= #{finProductCode}
and DATE_FORMAT(GENERATE_TIME,'%Y-%m-%d')=#{generateTime}
